      setModDefaultOnlineColor('#1e3a5f');
      setRequireEmailVerification(false);
      setBlockProxyVpnLogin(true);
      setBlockScriptUserAgentLogin(true);
      setBlockScriptUserAgentGameActions(true);
      setGameActionsClientStrict(false);
      setGameActionsTurnstileEnabled(false);
      setEntJoinTurnstileEnabled(false);
      setAttackTurnstileEnabled(false);
      setAttackTurnstileMasterDisabled(false);
      setAttackTurnstileMode('execute_only');
      setAttackTurnstileEnforce('off');
      setAttackTurnstileTargetUsernames('');
      setMinigameTurnstileEnabled(false);
      setMinigameTurnstileSiteKey('');
      setLoginTurnstileEnabled(false);
      setSustainedRlScopes(sustainedRlScopesPayload({}));
      setSustainedPageRlKillEnabled(true);
      setSustainedPageRlKillMaxGapMs('300');
      setSustainedPageRlKillSustainSec('12');
      setUserRequestPaceEnabled(false);
